"use strict";(globalThis.webpackChunkbook_source=globalThis.webpackChunkbook_source||[]).push([[190],{1096:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/hackathon/docs/preface","label":"Preface: An Introduction to Physical AI and Humanoid Robotics","docId":"preface","unlisted":false},{"type":"category","label":"Chapter 1: Introduction to Physical AI","items":[{"type":"link","href":"/hackathon/docs/chapter1/section1-physical-ai","label":"section1-physical-ai","docId":"chapter1/section1-physical-ai","unlisted":false},{"type":"link","href":"/hackathon/docs/chapter1/section2-digital-vs-physical-ai","label":"Section 2: Digital AI vs Physical AI","docId":"chapter1/section2-digital-vs-physical-ai","unlisted":false},{"type":"link","href":"/hackathon/docs/chapter1/section3-ai-in-bodies","label":"Section 3: AI Inside Bodies","docId":"chapter1/section3-ai-in-bodies","unlisted":false},{"type":"link","href":"/hackathon/docs/chapter1/section4-real-world-constraints","label":"Section 4: Real-World Constraints","docId":"chapter1/section4-real-world-constraints","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Part 2: The Robotic Nervous System (ROS 2)","items":[{"type":"link","href":"/hackathon/docs/part2-ros/chapter1-ros-architecture","label":"Chapter 1: The ROS 2 Architecture","docId":"part2-ros/chapter1-ros-architecture","unlisted":false},{"type":"link","href":"/hackathon/docs/part2-ros/chapter2-python-ros2-packages","label":"Chapter 2: Python ROS 2 Packages","docId":"part2-ros/chapter2-python-ros2-packages","unlisted":false},{"type":"link","href":"/hackathon/docs/part2-ros/chapter3-urdf","label":"Chapter 3: URDF","docId":"part2-ros/chapter3-urdf","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Part 3: The Digital Twin (Gazebo & Unity)","items":[{"type":"link","href":"/hackathon/docs/part3-digital-twin/chapter1-physics-simulation","label":"Chapter 1: Physics Simulation","docId":"part3-digital-twin/chapter1-physics-simulation","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"chapter1/section1-physical-ai":{"id":"chapter1/section1-physical-ai","title":"section1-physical-ai","description":"Physical AI, short for Physical Artificial Intelligence, refers to intelligent systems that interact directly with the real, tangible world. Unlike traditional digital AI, which lives inside computers and deals with information, Physical AI needs a body \u2013 a physical form \u2013 to sense, move, and make decisions in our environment. Think of it as giving AI a pair of eyes, hands, and legs, enabling it to go beyond virtual spaces and engage with objects and forces like gravity, friction, and resistance. This is the intelligence that powers robots, allowing it to perceive its surroundings, understand physics, and perform actions that have real-world consequences.","sidebar":"tutorialSidebar"},"chapter1/section2-digital-vs-physical-ai":{"id":"chapter1/section2-digital-vs-physical-ai","title":"Section 2: Digital AI vs Physical AI","description":"Welcome to the second section of our introduction to Physical AI. In the previous section, we explored the fundamental concepts of Physical AI. Now, we\'ll delve into a crucial distinction: the difference between Digital AI and Physical AI. Understanding this difference is key to appreciating the unique challenges and opportunities in the world of robotics.","sidebar":"tutorialSidebar"},"chapter1/section3-ai-in-bodies":{"id":"chapter1/section3-ai-in-bodies","title":"Section 3: AI Inside Bodies","description":"In the previous sections, we distinguished between the \\"minds\\" of Digital AI and Physical AI. Now, we dive into the fascinating world of the robot\'s \\"body.\\" How does an AI perceive the world, move, and obey the fundamental laws of reality? This section covers the three pillars that bring a robot to life: sensors (perception), motors (action), and the physics that governs it all.","sidebar":"tutorialSidebar"},"chapter1/section4-real-world-constraints":{"id":"chapter1/section4-real-world-constraints","title":"Section 4: Real-World Constraints","description":"If Physical AI had a motto, it might be: \\"It\'s more complicated in the real world.\\" While a digital AI operates in a perfect, predictable digital space, a Physical AI must confront the messy, unpredictable, and unforgiving nature of reality. These challenges, or \\"constraints,\\" are what make robotics so difficult and fascinating.","sidebar":"tutorialSidebar"},"part2-ros/chapter1-ros-architecture":{"id":"part2-ros/chapter1-ros-architecture","title":"Chapter 1: The ROS 2 Architecture","description":"Welcome to Part II of our journey into Physical AI. We\'re now moving from the \\"what\\" and \\"why\\" of robotics to the \\"how.\\" The single most important tool for building modern robots is the Robot Operating System (ROS), specifically ROS 2. Think of it as the central nervous system for a robot. It\u2019s the framework that allows all the different parts\u2014sensors, motors, and decision-making algorithms\u2014to communicate and work together as a single, coherent system. ROS provides services designed for a heterogeneous computer cluster, including hardware abstraction, low-level device control, implementation of common functionality, message-passing between processes, and package management. This chapter will explain the core architectural components of ROS, focusing on ROS 2, which offers improved real-time performance, security, and multi-robot capabilities compared to its predecessor.","sidebar":"tutorialSidebar"},"part2-ros/chapter2-python-ros2-packages":{"id":"part2-ros/chapter2-python-ros2-packages","title":"Chapter 2: Python ROS 2 Packages","description":"(This chapter is designed to be 600-800 words, beginner-friendly, technically accurate, and aligned with the course outline.)","sidebar":"tutorialSidebar"},"part2-ros/chapter3-urdf":{"id":"part2-ros/chapter3-urdf","title":"Chapter 3: URDF","description":"What is URDF?","sidebar":"tutorialSidebar"},"part3-digital-twin/chapter1-physics-simulation":{"id":"part3-digital-twin/chapter1-physics-simulation","title":"Chapter 1: Physics Simulation","description":"Welcome to Chapter 1: Physics Simulation! In this chapter, we\'ll explore how digital worlds mimic the real world, focusing on the fundamental physics that bring virtual objects to life.","sidebar":"tutorialSidebar"},"preface":{"id":"preface","title":"Preface: An Introduction to Physical AI and Humanoid Robotics","description":"(1) What This Book Is About","sidebar":"tutorialSidebar"}}}}')}}]);